import{F as t}from"./chunks/FigureContainer.zzqKkC_T.js";import{H as l}from"./chunks/HighLightText.xFkhFkD_.js";import{R as r}from"./chunks/ResourceCard.2BfY0ozu.js";import{c as o,o as d,a as n,b as e,d as p,e as a,w as i}from"./chunks/vitepress-theme-teek.BmVBWFw5.js";/* empty css                                                                               *//* empty css                                                             */const b={class:"tip custom-block"},T=JSON.parse('{"title":"上下文窗口：从“工作记忆”到能力边界","description":"深入解析上下文窗口的定义、O(n²) 注意力复杂度瓶颈、Lost in the Middle 现象及其工程影响，并对比 NTK-aware Scaling、YaRN 等长上下文优化技术，为应用设计中的上下文管理提供实践指导。","frontmatter":{"date":"2026-06-29T09:06:22.000Z","title":"上下文窗口：从“工作记忆”到能力边界","tldr":"上下文窗口是大模型的「工作记忆」——O(n²) 注意力计算是其扩展瓶颈，Lost in the Middle 效应让中间信息易被忽视。","description":"深入解析上下文窗口的定义、O(n²) 注意力复杂度瓶颈、Lost in the Middle 现象及其工程影响，并对比 NTK-aware Scaling、YaRN 等长上下文优化技术，为应用设计中的上下文管理提供实践指导。","tags":["概念","上下文窗口","注意力机制","Lost 中间象","RoPE"],"categories":["大模型基础","核心概念"],"permalink":"/llm-basic/context-window"},"headers":[],"relativePath":"llm-basic/context-window.md","filePath":"22.大模型基础/02.核心概念/03.上下文窗口.md"}'),c={name:"llm-basic/context-window.md"},v=Object.assign(c,{setup(u){return(m,s)=>(d(),o("div",null,[s[6]||(s[6]=n("h1",{id:"上下文窗口-从-工作记忆-到能力边界",tabindex:"-1"},[a("上下文窗口：从“工作记忆”到能力边界 "),n("a",{class:"header-anchor",href:"#上下文窗口-从-工作记忆-到能力边界","aria-label":"Permalink to “上下文窗口：从“工作记忆”到能力边界”"},"​")],-1)),s[7]||(s[7]=n("blockquote",null,[n("p",null,[n("strong",null,"摘要"),a(": 上下文窗口作为 LLM 的「工作记忆」，其容量直接决定了模型处理长文档、多轮对话和大型代码库的能力边界。本文从上下文窗口的基本定义与三种典型应用场景出发，深入剖析了 Attention 机制 O(n²) 计算复杂度对窗口扩展的根本制约，以及 Flash Attention 等工程优化未能改变的数学本质。在此基础上，本文详细讨论了 Lost in the Middle 现象——LLM 对上下文中间位置信息的系统性忽视——及其对 Prompt 设计的实践启示。最后，系统对比了 NTK-aware Scaling、YaRN 和 RoPE 线性插值三种核心扩展技术的原理与适用场景。全文为理解长上下文的性能边界、技术取舍与工程最佳实践提供了完整框架。")])],-1)),e(r,{resource:{name:"图集速览：上下文窗口——从“工作记忆”到能力边界",description:"如果你对上下文窗口与长文本处理还比较陌生，建议先读这篇图集速览。用可视化图片集合和要点摘要，帮你快速理清 LLM 工作记忆的核心概念。",url:"https://mp.weixin.qq.com/s/cfBok1gp-yaaEdcW8DwUMg",type:"article",tags:["上下文窗口","Attention","RoPE","LLM"]}}),s[8]||(s[8]=n("h2",{id:"_1-定义与意义",tabindex:"-1"},[a("1. 定义与意义 "),n("a",{class:"header-anchor",href:"#_1-定义与意义","aria-label":"Permalink to “1. 定义与意义”"},"​")],-1)),s[9]||(s[9]=n("p",null,[n("strong",null,"上下文窗口（Context Window）"),a(" 是 "),n("strong",null,"LLM 一次能够处理的最大 token 数"),a('。它就像模型的"工作记忆"——在这个窗口内的所有信息，模型都可以同时参考；窗口之外的，模型完全不可见。')],-1)),e(t,{type:"image",content:"https://insight-stack-1252300811.cos.ap-shanghai.myqcloud.com/img/llm-basic/llm-concept/context_window.png",caption:""}),s[10]||(s[10]=p(`<div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>上下文窗口 = 模型的&quot;视野范围&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>          窗口边界（如 128K tokens）</span></span>
<span class="line"><span>┌──────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ Token₁ Token₂ Token₃ ... Token 100 ... Token 128000 │  ← 模型能&quot;看到&quot;</span></span>
<span class="line"><span>└──────────────────────────────────────────────────┘</span></span>
<span class="line"><span>                                                        ↑ 窗口之外：模型无法知晓</span></span>
<span class="line"><span>                                                     Token 128001 Token 128002 ...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">为什么窗口大小如此关键？</p><p>三个实际场景说明：</p><ol><li><strong>长文档分析</strong>：分析一份 5 万字的合同，如果窗口只有 4K（约 3000 字），你需要把合同切成十几个片段分批送入，每段之间模型会&quot;忘记&quot;上下文，无法建立跨段落的关联。</li><li><strong>多轮对话</strong>：与你聊了 50 轮，如果窗口不够大，模型只能&quot;记住&quot;最近几轮，前面的对话内容会被&quot;遗忘&quot;。</li><li><strong>代码库理解</strong>：一个中等项目可能有几十万行代码。128K 上下文才能让模型一次性理解整个项目的结构。</li></ol></div><h2 id="_3-上下文窗口与注意力复杂度的关系-o-n2-难题" tabindex="-1">3. 上下文窗口与注意力复杂度的关系：O(n²) 难题 <a class="header-anchor" href="#_3-上下文窗口与注意力复杂度的关系-o-n2-难题" aria-label="Permalink to “3. 上下文窗口与注意力复杂度的关系：O(n²) 难题”">​</a></h2><p>上下文窗口并非越大越好，因为标准 Attention 机制的<strong>计算量和显存占用随 token 数平方级增长</strong>：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Attention 计算 QKᵀ 矩阵：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>n = 4K tokens:   4096 × 4096 = 16,777,216 次点积运算    (~1,670 万)</span></span>
<span class="line"><span>n = 32K tokens:  32768 × 32768 = 1,073,741,824 次       (~10 亿)</span></span>
<span class="line"><span>n = 128K tokens: 131072 × 131072 = 17,179,869,184 次     (~171 亿)</span></span>
<span class="line"><span>n = 1M tokens:   1,000,000² = 1,000,000,000,000 次       (~1 万亿！)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>每层都要算一次！x 96 层（GPT-3）→ 天文数字</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>QKᵀ 矩阵大小示意图：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>n=4K  ████                                      (小方块)</span></span>
<span class="line"><span>n=8K  ████████</span></span>
<span class="line"><span>n=16K ████████████████</span></span>
<span class="line"><span>n=32K ████████████████████████████████</span></span>
<span class="line"><span>n=1M  ██████████████████████████████████████████████... (巨大)</span></span>
<span class="line"><span>      ← 边长 = token 数，面积 = token 数² = 计算量 →</span></span>
<span class="line"><span></span></span>
<span class="line"><span>图中每个像素代表一对 token 之间的一对注意力分数计算</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p><strong>这就是&quot;长上下文 = 贵&quot;的根本原因。</strong></p><p>处理 128K token 上下文的计算量是处理 4K 的 1024 倍。Flash Attention 通过分块计算降低 IO 开销，但并未改变 O(n²) 的数学本质。</p><h2 id="_4-lost-in-the-middle-现象" tabindex="-1">4. Lost in the Middle 现象 <a class="header-anchor" href="#_4-lost-in-the-middle-现象" aria-label="Permalink to “4. Lost in the Middle 现象”">​</a></h2>`,9)),n("p",null,[s[1]||(s[1]=n("strong",null,"Lost in the Middle（中间信息丢失）",-1)),s[2]||(s[2]=a(" 是 2023 年由斯坦福、伯克利和 Samaya 团队在论文中系统揭示的现象：",-1)),e(l,{bold:""},{default:i(()=>[...s[0]||(s[0]=[a("当上下文变长时，LLM 对中间位置的信息提取能力显著下降，对开头和结尾的信息则保持较好。",-1)])]),_:1})]),s[11]||(s[11]=p(`<div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Lost in the Middle 效应示意（信息提取准确率随位置变化）：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>准确率</span></span>
<span class="line"><span>  ↑</span></span>
<span class="line"><span>  │  ● 开头：85%</span></span>
<span class="line"><span>  │        ●─┐</span></span>
<span class="line"><span>  │          │ 准确率持续下降...</span></span>
<span class="line"><span>  │          │               ┌─●</span></span>
<span class="line"><span>  │          └───────────────┘   结尾：82%</span></span>
<span class="line"><span>  │            中间：仅 40-60%</span></span>
<span class="line"><span>  └────────────────────────────────────→ 信息在上下文中的位置</span></span>
<span class="line"><span>    开头                              结尾</span></span>
<span class="line"><span></span></span>
<span class="line"><span>（数据来源：Lost in the Middle, Liu et al., 2023）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><p><strong>这意味着</strong>：你不能想当然地把最重要的信息放在上下文中间的某个位置——模型可能几乎&quot;读&quot;不到它。</p><p><strong>实用的缓解策略</strong>：</p><ul><li>将关键信息（指令、约束条件）放在上下文的开头或结尾</li><li>在长文档中多次重复关键约束</li><li>使用 RAG 时，将检索到的相关片段放在 prompt 的前后两端</li></ul><h2 id="_5-长上下文的优化技术" tabindex="-1">5. 长上下文的优化技术 <a class="header-anchor" href="#_5-长上下文的优化技术" aria-label="Permalink to “5. 长上下文的优化技术”">​</a></h2><p>业界已发展出多种技术，能够在无需重新训练或仅需轻量微调的情况下，将上下文窗口大幅扩展至数倍甚至数十倍。</p><p>核心都是围绕 <strong>RoPE（旋转位置编码）</strong> 的改进：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>RoPE 核心公式回顾：旋转角度 θᵢ = base^{-2i/d}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>位置 m 和位置 n 的注意力分数 ∝ cos((m-n)θ)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>训练时见过的最大距离 = L_train（如 4096）</span></span>
<span class="line"><span>测试时外推的距离 = L_test（如 16384，远超训练）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>直接外推的问题：模型没见过这么大的 (m-n)，注意力模式崩溃</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p><strong>三种核心扩展技术对比：</strong></p><table tabindex="0"><thead><tr><th>技术</th><th>核心做法</th><th>效果</th><th>代表模型</th></tr></thead><tbody><tr><td><strong>NTK-aware Scaling</strong></td><td>改变 RoPE 的 base 频率（如从 10000 改到 500000），让高频维度对长距离更敏感</td><td>4K → 16K 不微调即可用</td><td>Llama 生态广泛使用</td></tr><tr><td><strong>YaRN</strong>（Yet another RoPE extensioN）</td><td>NTK + 按维度分组缩放 + 温度调节 softmax</td><td>4K → 128K，无需微调</td><td>LLaMA 2 4K→128K</td></tr><tr><td><strong>RoPE 线性插值</strong></td><td>将位置索引线性压缩（m → m × L_train/L_test）</td><td>简单直接，但需微调</td><td>Meta Llama 早期扩展</td></tr><tr><td><strong>训练时扩展</strong></td><td>直接在更长序列上训练（如 CodeLlama 用 16K 训练）</td><td>效果最好</td><td>GPT-4、Claude</td></tr></tbody></table><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>NTK-aware Scaling 的直观类比：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>将收音机从&quot;本地频率&quot;调到&quot;短波频率&quot;——调谐旋钮（base 值）一转，</span></span>
<span class="line"><span>以前只能收到近距离台（4K token 内），现在能收到远距离台（32K token 外）。</span></span>
<span class="line"><span>模型参数本身没变，只是&quot;收听参数&quot;调整了。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div>`,11)),n("div",b,[s[4]||(s[4]=n("p",{class:"custom-block-title"},"一句话总结",-1)),s[5]||(s[5]=n("p",null,"长上下文是 2024-26 年 LLM 最核心的能力之一，但它的代价是 O(n²) 计算和 Lost in the Middle 效应。",-1)),e(l,{bold:"",type:"note"},{default:i(()=>[...s[3]||(s[3]=[a("在应用设计中，能用完 128K 是例外而非常态，合理的上下文管理和压缩往往比单纯追求更大窗口更重要。",-1)])]),_:1})])]))}});export{T as __pageData,v as default};
